import{_ as e,o as n,c as s,ag as t}from"./chunks/framework.Dx86EdC1.js";const g=JSON.parse('{"title":"Alur Permohonan Surat","description":"","frontmatter":{},"headers":[],"relativePath":"panduan-pengguna/permohonan-surat.md","filePath":"panduan-pengguna/permohonan-surat.md","lastUpdated":1791382762000}'),r={name:"panduan-pengguna/permohonan-surat.md"};function i(o,a,d,l,p,u){return n(),s("div",null,[...a[0]||(a[0]=[t(`<h1 id="alur-permohonan-surat" tabindex="-1">Alur Permohonan Surat <a class="header-anchor" href="#alur-permohonan-surat" aria-label="Permalink to &quot;Alur Permohonan Surat&quot;">​</a></h1><p>Menu <strong>E-Surat → Permohonan Surat</strong> (<code>/admin/letter-requests</code>) adalah jantung pelayanan persuratan.</p><h2 id="status-alur-persetujuan" tabindex="-1">Status &amp; Alur Persetujuan <a class="header-anchor" href="#status-alur-persetujuan" aria-label="Permalink to &quot;Status &amp; Alur Persetujuan&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Warga/Operator ajukan</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>  ┌─ pending_rt ──── Menunggu Verifikasi RT/RW</span></span>
<span class="line"><span>  ↓ (verify-rt / bypass-rt)</span></span>
<span class="line"><span>  ├─ pending_staff ─ Menunggu Verifikasi Staf Desa</span></span>
<span class="line"><span>  ↓ (verify-staff)</span></span>
<span class="line"><span>  ├─ pending_kades ─ Menunggu TTE Kepala Desa</span></span>
<span class="line"><span>  ↓ (approve-kades)</span></span>
<span class="line"><span>  └─ approved ────── Selesai &amp; Disahkan → PDF + QR</span></span>
<span class="line"><span>        ↘ rejected   Ditolak (oleh staf/kades, dengan alasan)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Status</th><th>Label</th><th>Aksi yang boleh dilakukan</th></tr></thead><tbody><tr><td><code>pending_rt</code></td><td>Menunggu Verifikasi RT/RW</td><td>Verifikasi oleh RT/perangkat</td></tr><tr><td><code>pending_staff</code></td><td>Menunggu Verifikasi Staf Desa</td><td>Verifikasi staf (perangkat)</td></tr><tr><td><code>pending_kades</code></td><td>Menunggu TTE Kades</td><td>Persetujuan + TTE Kepala Desa</td></tr><tr><td><code>approved</code></td><td>Selesai &amp; Disahkan</td><td>Unduh PDF</td></tr><tr><td><code>rejected</code></td><td>Ditolak</td><td>Lihat alasan, warga bisa ajukan ulang</td></tr></tbody></table><h3 id="siapa-yang-memproses" tabindex="-1">Siapa yang memproses? <a class="header-anchor" href="#siapa-yang-memproses" aria-label="Permalink to &quot;Siapa yang memproses?&quot;">​</a></h3><ul><li><strong>Ketua RT</strong> (<code>letters.verify_rt</code>) — verifikasi pengantar di tingkat RT.</li><li><strong>Perangkat Desa</strong> (<code>letters.process</code>) — cek berkas, verifikasi staf.</li><li><strong>Kepala Desa</strong> (<code>letters.approve</code>) — persetujuan akhir + TTE elektronik.</li><li><strong>Superadmin</strong> — dapat memproses pada status mana pun (termasuk <em>bypass</em> RT).</li></ul><h2 id="langkah-operator" tabindex="-1">Langkah Operator <a class="header-anchor" href="#langkah-operator" aria-label="Permalink to &quot;Langkah Operator&quot;">​</a></h2><ol><li>Buka <strong>E-Surat → Permohonan Surat</strong>; filter antrean berdasarkan status.</li><li>Klik permohonan untuk melihat detail: pemohon, template, isian field, dan dokumen.</li><li>Proses sesuai status Anda: <ul><li><strong>Verifikasi RT</strong> — cocokkan data pemohon dengan wilayah RT.</li><li><strong>Verifikasi Staf</strong> — pastikan berkas/kelengkapan.</li><li><strong>Setujui &amp; TTE</strong> — Kepala Desa; sistem menomori surat, menandatangani, dan men-generate QR.</li><li><strong>Tolak</strong> — wajib mengisi alasan; status menjadi <code>rejected</code>.</li></ul></li><li><strong>Unduh PDF</strong> — dokumen sudah berisi nomor surat, QR verifikasi, dan identitas desa.</li></ol><h2 id="verifikasi-keaslian-surat" tabindex="-1">Verifikasi Keaslian Surat <a class="header-anchor" href="#verifikasi-keaslian-surat" aria-label="Permalink to &quot;Verifikasi Keaslian Surat&quot;">​</a></h2><p>Setiap PDF memuat QR Code yang menautkan ke:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://domain-anda/verify/letter/{qr_token}</span></span></code></pre></div><p>Pihak ketiga (mis. penerima surat) cukup memindai QR untuk memastikan surat asli dan melihat statusnya — tanpa membuka data pribadi lain.</p><h2 id="batasan-pemrosesan" tabindex="-1">Batasan Pemrosesan <a class="header-anchor" href="#batasan-pemrosesan" aria-label="Permalink to &quot;Batasan Pemrosesan&quot;">​</a></h2><p><code>LetterRequest::canBeProcessedBy()</code> memastikan:</p><ul><li>Permohonan yang sudah <code>approved</code>/<code>rejected</code> <strong>tidak</strong> bisa diproses ulang.</li><li>Aksi sesuai permission role masing-masing (lihat <a href="/panduan-pengembang/otorisasi.html">Role &amp; Otorisasi</a>).</li></ul><h2 id="unduh-pdf-massal" tabindex="-1">Unduh PDF Massal <a class="header-anchor" href="#unduh-pdf-massal" aria-label="Permalink to &quot;Unduh PDF Massal&quot;">​</a></h2><p>Saat ini unduhan bersifat per-permohonan (<code>/admin/letter-requests/{id}/pdf</code>). Portal warga juga menyediakan unduhan mandiri di <a href="/panduan-pengguna/portal-warga.html">Portal Warga</a>.</p>`,18)])])}const m=e(r,[["render",i]]);export{g as __pageData,m as default};
